555	// strictCircuitObject decodes one committed circuit record's own member map,
556	// demanding a JSON object with exactly the known top-level fields once.
557	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
558		return strictObjectMembers(raw, what, persistCircuitFields)
559	}
560	
561	// checkStoredNameEncoding enforces the circuit-name identity rule on the raw
562	// JSON string token of a committed circuit record's name field. The string
563	// has already been decoded by the strict member read, so the token is known
564	// to be one complete, well-formed JSON string; this walk judges only what
565	// that decode silently repairs:
566	//
567	//   - invalid UTF-8 bytes in the literal (unescaped) portions — a lone
568	//     continuation byte, a truncated multi-byte character, an overlong
569	//     form — which encoding/json rewrites to U+FFFD, and
570	//   - \uXXXX escapes forming an unpaired surrogate — a high surrogate not
571	//     immediately followed by its low-surrogate escape, or a low surrogate
572	//     standing alone — which are rewritten to U+FFFD the same way.
573	//
574	// Both would make the record read back under a different name than the bytes
575	// on disk carry, so the record is data corruption rather than a circuit
576	// named with a replacement character it never had. A legal surrogate pair
577	// decodes to its astral character, an actually committed "�" (written
578	// directly or as a U+FFFD escape) is an ordinary name, and the literal six
579	// characters "\uD800" — written with an escaped backslash — carry no escape
580	// at all: all three keep their exact value. Only the name field is judged
581	// here; every other field keeps the ordinary decoding rules.
582	func checkStoredNameEncoding(raw json.RawMessage, what string) error {
583		token := bytes.TrimSpace(raw)
584		// The token is a complete JSON string (the strict string read above
585		// succeeded), so every escape is well-formed and the walk stays in
586		// bounds; only the replacement-prone content is judged.
587		for i := 1; i < len(token)-1; {
588			c := token[i]
589			if c == '\\' {
590				if token[i+1] != 'u' {
591					i += 2 // a simple escape: \" \\ \/ \b \f \n \r \t
592					continue
593				}
594				code, _ := strconv.ParseUint(string(token[i+2:i+6]), 16, 32)
595				switch {
596				case code >= 0xD800 && code <= 0xDBFF:
597					// A high surrogate is whole only when its low-surrogate
598					// escape follows immediately.
599					if i+12 <= len(token) && token[i+6] == '\\' && token[i+7] == 'u' {
600						lo, _ := strconv.ParseUint(string(token[i+8:i+12]), 16, 32)
601						if lo >= 0xDC00 && lo <= 0xDFFF {
602							i += 12
603							continue
604						}
605					}
606					return corruptf("%s contains an unpaired high surrogate escape (\\u%04X); the committed name would not read back unchanged", what, code)
607				case code >= 0xDC00 && code <= 0xDFFF:
608					return corruptf("%s contains an unpaired low surrogate escape (\\u%04X); the committed name would not read back unchanged", what, code)
609				}
610				i += 6
611				continue
612			}
613			if c < utf8.RuneSelf {
614				i++
615				continue
616			}
617			r, size := utf8.DecodeRune(token[i:])
618			if r == utf8.RuneError && size == 1 {
619				return corruptf("%s contains invalid UTF-8 bytes; the committed name would not read back unchanged", what)
620			}
621			i += size
622		}
623		return nil
624	}
625	
626	// strictObjectMembers decodes one committed record's own member map,
627	// demanding a JSON object without repeated keys. A non-nil allowed list
628	// restricts which keys may appear; nil allows any key. It scans only the
629	// record's own level: the envelope scanner already attributes a duplicated
630	// top-level key to this record, and nested values such as the constraint
631	// definition own their (more precise) strict decoders. Keys are compared
632	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
633	// still a duplicate, even when both values are identical.
634	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
635		trimmed := bytes.TrimSpace(raw)
636		if len(trimmed) == 0 || trimmed[0] != '{' {
637			return nil, corruptf("%s must be a JSON object", what)
638		}
639		dec := json.NewDecoder(bytes.NewReader(trimmed))
640		dec.UseNumber()
641		open, err := dec.Token()
642		if err != nil || open != json.Delim('{') {
643			return nil, corruptf("%s must be a JSON object", what)
644		}
645		var allowed map[string]bool
646		if allowedFields != nil {
647			allowed = make(map[string]bool, len(allowedFields))
648			for _, f := range allowedFields {
649				allowed[f] = true
650			}
651		}
652		members := make(map[string]json.RawMessage)
653		for dec.More() {
654			keyTok, err := dec.Token()
655			if err != nil {
656				return nil, corruptf("%s is not valid JSON: %v", what, err)
657			}
658			key, ok := keyTok.(string)
659			if !ok {
660				return nil, corruptf("%s is not valid JSON", what)
661			}
662			if allowed != nil && !allowed[key] {
663				return nil, corruptf("%s has unknown field %q", what, key)
664			}
665			if _, repeated := members[key]; repeated {
666				return nil, corruptf("%s contains duplicate field %q", what, key)
667			}
668			var value json.RawMessage
669			if err := dec.Decode(&value); err != nil {
670				return nil, corruptf("%s is not valid JSON: %v", what, err)
671			}
672			members[key] = value
673		}
674		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
675			return nil, corruptf("%s is not valid JSON", what)
676		}
677		if _, err := dec.Token(); err != io.EOF {
678			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
679		}
680		return members, nil
681	}
