688	// Store is a persistent workbench backed by one local data directory.
689	//
690	// All operations are safe for concurrent use by multiple goroutines and by
691	// several processes pointed at the same directory: an in-process mutex plus a
692	// process-shared flock serialize commits, and every commit is an atomic
693	// temp-file/fsync/rename replacement. Open the directory with Open and call
694	// Close when done.
695	type Store struct {
696		dir  string
697		mu   sync.Mutex
698		lock *os.File
699	
700		data envelope
701	}
702	
703	// Open opens (creating if needed) the workbench data in dir. If the
704	// directory does not exist it is created. Existing committed data is loaded
705	// and fully validated before Open returns; on a corrupt, truncated or
706	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
707	// leaves every file in the directory untouched.
708	func Open(dir string) (*Store, error) {
709		if dir == "" {
710			return nil, invalidf("data directory must not be empty")
711		}
712		if err := os.MkdirAll(dir, 0o755); err != nil {
713			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
714		}
715		lockPath := filepath.Join(dir, dirLockFile)
716		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
717		if err != nil {
718			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
719		}
720		// Serialize against other processes while we read / validate.
721		if err := lockExclusive(lock); err != nil {
722			lock.Close()
723			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
724		}
725	
726		s := &Store{dir: dir, lock: lock}
727		if err := s.loadLocked(); err != nil {
728			unlockLock(lock)
729			lock.Close()
730			return nil, err
731		}
732		// The lock is taken again per operation; holding it for the store's
733		// lifetime would forbid two open handles on one directory.
734		if err := unlockLock(lock); err != nil {
735			lock.Close()
736			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
737		}
738		return s, nil
739	}
740	
741	// Close releases the directory lock. It does not discard committed data.
742	func (s *Store) Close() error {
743		s.mu.Lock()
744		defer s.mu.Unlock()
745		if s.lock == nil {
746			return nil
747		}
748		var first error
749		if err := unlockLock(s.lock); err != nil {
750			first = err
751		}
752		if err := s.lock.Close(); err != nil && first == nil {
753			first = err
754		}
755		s.lock = nil
756		return first
757	}
758	
759	// Dir reports the data directory backing the store.
760	func (s *Store) Dir() string { return s.dir }
761	
762	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
763	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
764	
765	// loadLocked reads and validates the committed file. Caller must hold the
766	// exclusive flock; the in-process mutex is taken by the public Open path.
767	func (s *Store) loadLocked() error {
768		raw, err := os.ReadFile(s.dataPath())
769		if errors.Is(err, os.ErrNotExist) {
770			s.data = envelope{Format: FormatVersion}
771			return nil
772		}
773		if err != nil {
774			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
775		}
776		if len(strings.TrimSpace(string(raw))) == 0 {
777			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
778		}
779	
780		var env envelope
781		if err := json.Unmarshal(raw, &env); err != nil {
782			// Shape failures surfaced by the persisted-definition decoders are
783			// integrity failures, not JSON syntax errors; report their detail
784			// instead of the generic "not valid JSON" wording.
785			var se StoreError
786			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
787				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
788			}
789			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
790		}
791		if env.Format == 0 {
792			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
793		}
794		if env.Format != FormatVersion {
795			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
796				s.dataPath(), env.Format, FormatVersion)
797		}
798		if err := validateEnvelope(env); err != nil {
799			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
800		}
801		s.data = env
802		return nil
803	}
804	
805	// commitLocked writes the pending state atomically: temp file → fsync →
806	// rename → fsync directory. Caller must hold both the in-process mutex and
807	// the exclusive flock; all in-memory mutations must already have happened and
808	// been rule-checked, so a failure here occurs before any success is reported.
809	func (s *Store) commitLocked() error {
810		s.data.Format = FormatVersion
811		// Stable output: records are stored sorted so files are deterministic.
812		sortEnvelope(&s.data)
813	
814		payload, err := json.MarshalIndent(&s.data, "", "  ")
815		if err != nil {
816			return fmt.Errorf("cannot encode data: %w", err)
817		}
818		payload = append(payload, '\n')
819	
820		tmp := s.tmpPath()
821		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
822		if err != nil {
823			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
824		}
825		if _, err := f.Write(payload); err != nil {
826			f.Close()
827			os.Remove(tmp)
828			return fmt.Errorf("cannot write staged data: %w", err)
829		}
830		if err := f.Sync(); err != nil {
831			f.Close()
832			os.Remove(tmp)
833			return fmt.Errorf("cannot flush staged data: %w", err)
834		}
835		if err := f.Close(); err != nil {
836			os.Remove(tmp)
837			return fmt.Errorf("cannot finish staged data: %w", err)
838		}
839		if err := os.Rename(tmp, s.dataPath()); err != nil {
840			os.Remove(tmp)
841			return fmt.Errorf("cannot commit data file: %w", err)
842		}
843		if err := syncDir(s.dir); err != nil {
844			// The rename already happened; lack of dir fsync only weakens crash
845			// durability, never correctness of what is visible now.
846			return nil
847		}
848		return nil
849	}
850	
851	// withLock runs fn under the in-process mutex and an exclusive flock, then
852	// atomically commits when fn requests it. The on-disk state is re-read after
853	// acquiring the lock, so concurrent commits from another process or another
854	// handle are always observed. Operations validate before mutating; a rejected
855	// operation (commit=false or an error) writes nothing and leaves committed
856	// state unchanged.
857	func (s *Store) withLock(fn func() (commit bool, err error)) error {
858		s.mu.Lock()
859		defer s.mu.Unlock()
860		if s.lock == nil {
861			return invalidf("store is closed")
862		}
863		if err := lockExclusive(s.lock); err != nil {
864			return fmt.Errorf("cannot lock data directory: %w", err)
865		}
866		defer unlockLock(s.lock)
867	
868		if err := s.loadLocked(); err != nil {
869			return err
870		}
871		commit, err := fn()
872		if err != nil {
873			return err
874		}
875		if !commit {
876			return nil
877		}
878		return s.commitLocked()
879	}
880	
881	// withLockRead runs fn under a shared flock over freshly reloaded state.
882	func (s *Store) withLockRead(fn func() error) error {
883		s.mu.Lock()
884		defer s.mu.Unlock()
885		if s.lock == nil {
886			return invalidf("store is closed")
887		}
888		if err := lockShared(s.lock); err != nil {
889			return fmt.Errorf("cannot lock data directory: %w", err)
890		}
891		defer unlockLock(s.lock)
892		if err := s.loadLocked(); err != nil {
893			return err
894		}
895		return fn()
896	}
