898	func sortEnvelope(env *envelope) {
899		sort.Slice(env.Circuits, func(i, j int) bool {
900			if env.Circuits[i].Name != env.Circuits[j].Name {
901				return env.Circuits[i].Name < env.Circuits[j].Name
902			}
903			return env.Circuits[i].Version < env.Circuits[j].Version
904		})
905		sort.Slice(env.Setups, func(i, j int) bool {
906			if env.Setups[i].Name != env.Setups[j].Name {
907				return env.Setups[i].Name < env.Setups[j].Name
908			}
909			return env.Setups[i].Version < env.Setups[j].Version
910		})
911		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
912		sort.Slice(env.Artifacts, func(i, j int) bool {
913			if env.Artifacts[i].Name != env.Artifacts[j].Name {
914				return env.Artifacts[i].Name < env.Artifacts[j].Name
915			}
916			return env.Artifacts[i].Version < env.Artifacts[j].Version
917		})
918	}
