180			// committing anything.
181			if !hasField {
182				result = circuitFromPersist(*existing)
183				return false, nil
184			}
185			result = applyCircuitMutation(existing, mutation)
186			return true, nil
187		})
188		return result, err
189	}
190	
191	// --- draft update internals -----------------------------------------------
192	//
193	// circuitMutation is the complete set of updatable draft fields one
194	// modification would leave committed: the three counts and the description.
195	// Both public update entry points resolve their request into this type —
196	// UpdateCircuit takes all four values from the request, UpdateCircuitPartial
197	// merges request fields over the stored record — and then share the same
198	// count rules, imported-definition compatibility check and commit, so the
199	// two usages can never drift apart. A mutation never replaces the stored
200	// constraint definition; it is only checked against it.
201	type circuitMutation struct {
202		Constraints   int
203		PublicInputs  int
204		PrivateInputs int
205		Description   string
206	}
207	
208	// validateMutationCounts holds the basic count rules for any draft update:
209	// constraints must be greater than zero and both input counts must not be
210	// negative. The rules are judged on the mutation's complete resulting
211	// counts, not on the supplied fields alone.
212	func validateMutationCounts(m circuitMutation) error {
213		return validateCounts(m.Constraints, m.PublicInputs, m.PrivateInputs)
214	}
215	
216	// validateMutationDefinition holds the rule shared with imported
217	// definitions: when the version already has one, the mutation's complete
218	// resulting counts must keep it legal — exactly as many constraints as the
219	// definition and every referenced wire inside the resulting public/private
220	// input layout. An unreadable stored definition is reported as data
221	// corruption. A version without a definition imposes no extra rule.
222	func validateMutationDefinition(existing persistCircuit, m circuitMutation) error {
223		if existing.Definition == nil {
224			return nil
225		}
226		parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
227		if perr != nil {
228			return corruptf("stored definition for %q v%d is unreadable: %v", existing.Name, existing.Version, perr)
229		}
230		if !parsed.compatibleWith(m.Constraints, m.PublicInputs, m.PrivateInputs) {
231			return invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
232		}
233		return nil
234	}
235	
236	// applyCircuitMutation commits a validated mutation onto the stored draft
237	// record, overwriting the three counts and the description together. The
238	// name, version, frozen flag and imported definition are never touched. The
239	// caller is responsible for all validation and for holding the store lock.
240	func applyCircuitMutation(existing *persistCircuit, m circuitMutation) Circuit {
241		existing.Constraints = m.Constraints
242		existing.PublicInputs = m.PublicInputs
243		existing.PrivateInputs = m.PrivateInputs
244		existing.Description = m.Description
245		return circuitFromPersist(*existing)
246	}
247	
248	// FreezeCircuit freezes a circuit version. Unknown versions yield
249	// ErrNotFound. Freezing an already-frozen version returns that version
250	// unchanged (idempotent). Once frozen, name, version and the three counts
251	// can never change again.
252	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
253		if err := validateCircuitKey(name, version); err != nil {
254			return Circuit{}, err
255		}
256	
257		var result Circuit
258		err := s.withLock(func() (bool, error) {
259			existing := findCircuit(s.data.Circuits, name, version)
260			if existing == nil {
261				return false, notFoundf("circuit %q version %d does not exist", name, version)
262			}
263			if existing.Frozen {
264				result = circuitFromPersist(*existing)
265				return false, nil
266			}
267			existing.Frozen = true
268			result = circuitFromPersist(*existing)
269			return true, nil
270		})
271		return result, err
272	}
273	
274	// CopyCircuit creates a new draft version of a circuit name by copying a
275	// frozen source version. The target version must be a positive integer
276	// different from the source version; it need not be consecutive or greater.
277	//
278	// The copy carries over the source's description, constraint count, public
279	// and private input counts, and — when the source has one — its complete
280	// constraint definition (modulus, constraint order and wire layout). A
281	// counts-only source produces a counts-only target with no definition. The
282	// new draft is fully independent: updating, re-importing or freezing it
283	// never touches the source, and the source's compiled artifacts, trusted
284	// setup and registered jobs are never copied or bound to the target. The
285	// target must register its own setup and compile its own artifact after
286	// freezing; the source's hash cannot satisfy the target's input checks or
287	// job bindings.
288	//
289	// Copying is idempotent: if the target already exists as a draft whose
290	// description, counts and definition are semantically equal to the source,
291	// the stored target is returned unchanged and nothing is written. A frozen
292	// target or a target whose description, counts or definition has changed
293	// yields ErrConflict. An unknown source yields ErrNotFound and an unfrozen
294	// source ErrNotFrozen; the source is always checked before the target.
295	func (s *Store) CopyCircuit(name string, version, toVersion int) (Circuit, error) {
296		if err := validateCircuitKey(name, version); err != nil {
297			return Circuit{}, err
298		}
299		if err := validateCircuitKey(name, toVersion); err != nil {
300			return Circuit{}, err
301		}
302		if version == toVersion {
303			return Circuit{}, invalidf("source and target version must differ for circuit %q", name)
304		}
305	
306		var result Circuit
307		err := s.withLock(func() (bool, error) {
308			source := findCircuit(s.data.Circuits, name, version)
309			if source == nil {
310				return false, notFoundf("circuit %q version %d does not exist", name, version)
311			}
312			if !source.Frozen {
313				return false, notFrozenf("circuit %q version %d must be frozen before it can be copied as a new draft", name, version)
314			}
315			target := findCircuit(s.data.Circuits, name, toVersion)
316			if target != nil {
317				if target.Frozen {
318					return false, conflictf("circuit %q version %d already exists and is frozen", name, toVersion)
319				}
320				if !circuitCopyMatches(*source, *target) {
321					return false, conflictf("circuit %q version %d already exists with content that differs from the source", name, toVersion)
322				}
323				result = circuitFromPersist(*target)
324				return false, nil
325			}
326			record := persistCircuit{
327				Name: name, Version: toVersion,
328				Constraints: source.Constraints, PublicInputs: source.PublicInputs, PrivateInputs: source.PrivateInputs,
329				Frozen: false, Description: source.Description,
330			}
331			if source.Definition != nil {
332				def := *source.Definition
333				record.Definition = &def
334			}
335			s.data.Circuits = append(s.data.Circuits, record)
336			result = circuitFromPersist(record)
337			return true, nil
338		})
339		return result, err
340	}
341	
342	// RecordSetup records a trusted setup for one frozen circuit version. The
343	// record belongs exclusively to that name+version. Unknown versions yield
344	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
345	// setup for the same version is idempotent and adds no duplicate record.
346	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
347		if err := validateCircuitKey(name, version); err != nil {
348			return Setup{}, err
349		}
350	
351		var result Setup
352		err := s.withLock(func() (bool, error) {
353			circuit := findCircuit(s.data.Circuits, name, version)
354			if circuit == nil {
355				return false, notFoundf("circuit %q version %d does not exist", name, version)
356			}
357			if !circuit.Frozen {
358				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
359			}
360			if existing := findSetup(s.data.Setups, name, version); existing != nil {
361				result = setupFromPersist(*existing)
362				return false, nil
363			}
364			record := persistSetup{Name: name, Version: version}
365			s.data.Setups = append(s.data.Setups, record)
366			result = setupFromPersist(record)
367			return true, nil
368		})
369		return result, err
370	}
371	
372	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
373	// no proving computation runs, the accepted request alone is persisted.
374	//
375	// The job id must be non-empty and not only whitespace, circuit name and
376	// version must be explicit and Attempt must be positive. Failure reasons are
377	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
378	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
379	// refused submission leaves no job behind.
380	//
381	// A non-empty CompiledHash additionally binds the job to the pinned
382	// version's compiled artifact, matched as the exact string: a version with
383	// no compiled artifact yields ErrArtifactMissing and a hash that differs
384	// from that artifact's hash yields ErrArtifactMismatch. Artifacts of other
385	// names or versions never satisfy the binding. An empty CompiledHash leaves
386	// the job unbound and keeps the register-only behavior.
387	//
388	// Resubmitting the same id with the same request — including the same
389	// optional hash — returns the stored job; the same id with different content
390	// yields ErrConflict, reported before any artifact check of the new request.
391	// A stored job stays pinned to the version submitted, regardless of circuit
392	// versions added later.
393	func (s *Store) SubmitJob(job Job) (Job, error) {
394		if strings.TrimSpace(job.ID) == "" {
395			return Job{}, invalidf("job id must be non-empty and not only whitespace")
396		}
397		if strings.TrimSpace(job.Circuit) == "" {
398			return Job{}, invalidf("job %q must name a circuit", job.ID)
399		}
400		if job.Version <= 0 {
401			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
402		}
403		if job.Attempt <= 0 {
404			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
405		}
406		if job.Kind != "prove" {
407			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
408				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
409		}
410	
411		var result Job
412		err := s.withLock(func() (bool, error) {
413			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
414				if !sameJobRequest(*existing, job) {
415					return false, conflictf("job %q already exists with a different request", job.ID)
416				}
417				result = jobFromPersist(*existing)
418				return false, nil
419			}
420			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
421			if circuit == nil {
422				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
423			}
424			if !circuit.Frozen {
425				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
426			}
427			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
428				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
429					job.ID, job.Circuit, job.Version)
430			}
431			if job.CompiledHash != "" {
432				artifact := findArtifact(s.data.Artifacts, job.Circuit, job.Version)
433				if artifact == nil {
434					return false, artifactMissingf("job %q references circuit %q version %d which has no compiled artifact",
435						job.ID, job.Circuit, job.Version)
436				}
437				if artifact.Hash != job.CompiledHash {
438					return false, artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
439						job.CompiledHash, job.Circuit, job.Version, artifact.Hash)
440				}
441			}
442			record := persistJob{
443				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
444				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
445				CompiledHash: job.CompiledHash,
446			}
447			s.data.Jobs = append(s.data.Jobs, record)
448			result = jobFromPersist(record)
449			return true, nil
450		})
451		return result, err
452	}
453	
454	// GetCircuit returns one circuit version, sorted-field populated exactly as
455	// stored. Unknown versions yield ErrNotFound.
456	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
457		if err := validateCircuitKey(name, version); err != nil {
458			return Circuit{}, err
459		}
460		var result Circuit
461		err := s.withLockRead(func() error {
462			existing := findCircuit(s.data.Circuits, name, version)
463			if existing == nil {
464				return notFoundf("circuit %q version %d does not exist", name, version)
465			}
466			result = circuitFromPersist(*existing)
467			return nil
468		})
469		return result, err
470	}
471	
472	// ListCircuits returns all stored circuit versions ordered by circuit name
473	// (lexicographically) and then by ascending version number.
474	func (s *Store) ListCircuits() ([]Circuit, error) {
475		var result []Circuit
476		err := s.withLockRead(func() error {
477			ordered := append([]persistCircuit(nil), s.data.Circuits...)
478			sort.Slice(ordered, func(i, j int) bool {
479				if ordered[i].Name != ordered[j].Name {
480					return ordered[i].Name < ordered[j].Name
481				}
482				return ordered[i].Version < ordered[j].Version
483			})
484			result = make([]Circuit, len(ordered))
485			for i, c := range ordered {
486				result[i] = circuitFromPersist(c)
487			}
488			return nil
489		})
490		return result, err
491	}
492	
493	// GetSetup reports whether a trusted setup is registered for the named
494	// frozen version. A missing record yields ErrNotFound.
495	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
496		if err := validateCircuitKey(name, version); err != nil {
497			return Setup{}, false, err
498		}
499		var result Setup
500		found := false
501		err := s.withLockRead(func() error {
502			existing := findSetup(s.data.Setups, name, version)
503			if existing == nil {
504				return nil
505			}
506			result = setupFromPersist(*existing)
507			found = true
508			return nil
509		})
510		return result, found, err
511	}
512	
513	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
514	func (s *Store) GetJob(id string) (Job, error) {
515		if strings.TrimSpace(id) == "" {
516			return Job{}, invalidf("job id must be non-empty and not only whitespace")
517		}
518		var result Job
519		err := s.withLockRead(func() error {
520			existing := findJob(s.data.Jobs, id)
521			if existing == nil {
522				return notFoundf("job %q does not exist", id)
523			}
524			result = jobFromPersist(*existing)
525			return nil
526		})
527		return result, err
528	}
529	
530	// ListJobs returns all accepted jobs ordered by job id lexicographically.
531	func (s *Store) ListJobs() ([]Job, error) {
532		var result []Job
533		err := s.withLockRead(func() error {
534			ordered := append([]persistJob(nil), s.data.Jobs...)
535			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
536			result = make([]Job, len(ordered))
537			for i, j := range ordered {
538				result[i] = jobFromPersist(j)
539			}
540			return nil
541		})
542		return result, err
543	}
544	
545	// --- validation helpers ---------------------------------------------------
546	
547	func validateCircuitKey(name string, version int) error {
548		if strings.TrimSpace(name) == "" {
549			return invalidf("circuit name must be non-empty and not only whitespace")
550		}
551		if version <= 0 {
552			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
553		}
554		return nil
555	}
556	
557	// maxInputWires is the largest declared input count that stays representable
558	// on the running platform. Wire numbering always reserves wire 0 for the
559	// constant one, so the wires a version names are 0 plus its public and private
560	// inputs: the declared counts must satisfy 1 + public + private <= M, where M
561	// is the largest positive value the platform's int can hold. The check is done
562	// without ever adding the counts, so a layout whose sum would wrap (e.g.
563	// public=M with one private input) is refused rather than accepted through
564	// integer wraparound as a small, representable layout.
565	const maxInputWires = math.MaxInt
566	
567	// inputLayoutRepresentable reports whether the constant wire plus the public
568	// and private inputs fits inside the platform's int. Callers already guarantee
569	// both counts are non-negative.
570	func inputLayoutRepresentable(publicInputs, privateInputs int) bool {
571		return publicInputs <= maxInputWires-1 && privateInputs <= maxInputWires-1-publicInputs
572	}
573	
574	func validateCounts(constraints, publicInputs, privateInputs int) error {
575		if constraints <= 0 {
576			return invalidf("constraints must be greater than zero, got %d", constraints)
577		}
578		if publicInputs < 0 {
579			return invalidf("public input count must not be negative, got %d", publicInputs)
580		}
581		if privateInputs < 0 {
582			return invalidf("private input count must not be negative, got %d", privateInputs)
583		}
584		if !inputLayoutRepresentable(publicInputs, privateInputs) {
585			return invalidf("input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
586				publicInputs, privateInputs, maxInputWires)
587		}
588		return nil
589	}
590	
591	// --- lookup / mapping helpers --------------------------------------------
592	
593	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
594		for i := range cs {
595			if cs[i].Name == name && cs[i].Version == version {
596				return &cs[i]
597			}
598		}
599		return nil
600	}
601	
602	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
603		for i := range ps {
604			if ps[i].Name == name && ps[i].Version == version {
605				return &ps[i]
606			}
607		}
608		return nil
609	}
610	
611	func findJob(js []persistJob, id string) *persistJob {
612		for i := range js {
613			if js[i].ID == id {
614				return &js[i]
615			}
616		}
617		return nil
618	}
619	
620	func sameJobRequest(stored persistJob, request Job) bool {
621		return stored.Circuit == request.Circuit &&
622			stored.Version == request.Version &&
623			stored.Kind == request.Kind &&
624			stored.Attempt == request.Attempt &&
625			stored.CompiledHash == request.CompiledHash
626	}
627	
628	func circuitFromPersist(c persistCircuit) Circuit {
629		return Circuit{
630			Name: c.Name, Version: c.Version,
631			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
632			Frozen: c.Frozen, Description: c.Description,
633		}
634	}
635	
636	// circuitCopyMatches reports whether target is the same draft content that a
637	// copy of source would create: same description, same three counts and a
638	// semantically equal constraint definition. Definition equality follows the
639	// existing normalization semantics (terms merged per wire, coefficients
640	// reduced modulo p, zeros dropped, wires sorted ascending); a missing
641	// definition differs from a present one.
642	func circuitCopyMatches(source, target persistCircuit) bool {
643		if source.Description != target.Description {
644			return false
645		}
646		if source.Constraints != target.Constraints ||
647			source.PublicInputs != target.PublicInputs ||
648			source.PrivateInputs != target.PrivateInputs {
649			return false
650		}
651		return definitionsEqual(source.Definition, target.Definition, source.PublicInputs, source.PrivateInputs)
652	}
653	
654	// definitionsEqual compares two stored definitions for semantic equality.
655	// Both nil is equal; one nil and the other not is different. When both are
656	// present they are parsed through the existing normalization pipeline and
657	// compared by modulus, constraint count and each side's wire/coefficient
658	// pairs. The public/private layout is the source's; the caller has already
659	// confirmed the counts match.
660	func definitionsEqual(d1, d2 *persistDefinition, public, private int) bool {
661		if d1 == nil && d2 == nil {
662			return true
663		}
664		if d1 == nil || d2 == nil {
665			return false
666		}
667		p1, err := definitionFromPersist(*d1, public, private)
668		if err != nil {
669			return false
670		}
671		p2, err := definitionFromPersist(*d2, public, private)
672		if err != nil {
673			return false
674		}
675		if p1.modulus != p2.modulus || len(p1.constraints) != len(p2.constraints) {
676			return false
677		}
678		for i := range p1.constraints {
679			if !canonicalTermsEqual(p1.constraints[i].a, p2.constraints[i].a) ||
680				!canonicalTermsEqual(p1.constraints[i].b, p2.constraints[i].b) ||
681				!canonicalTermsEqual(p1.constraints[i].c, p2.constraints[i].c) {
682				return false
683			}
684		}
685		return true
686	}
687	
688	// canonicalTermsEqual reports whether two normalized term slices are
689	// identical wire-by-wire and coefficient-by-coefficient.
690	func canonicalTermsEqual(t1, t2 []parsedTerm) bool {
691		if len(t1) != len(t2) {
692			return false
693		}
694		for i := range t1 {
695			if t1[i].wire != t2[i].wire || t1[i].value != t2[i].value {
696				return false
697			}
698		}
699		return true
700	}
701	
702	func setupFromPersist(p persistSetup) Setup {
703		return Setup{Name: p.Name, Version: p.Version}
704	}
705	
706	func jobFromPersist(j persistJob) Job {
707		return Job{
708			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
709			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
710			CompiledHash: j.CompiledHash,
711		}
712	}
